type PlatformIconProps = React.SVGProps<SVGSVGElement> & { size?: number | string }
function Facebook({ size = 24, ...props }: PlatformIconProps) {
  return <svg aria-hidden="true" viewBox="0 0 24 24" width={size} height={size} fill="none" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round" {...props}><circle cx="12" cy="12" r="9"/><path d="M13.25 20v-7h2.4l.35-2.65h-2.75V8.7c0-.77.22-1.3 1.37-1.3H16V5.04c-.6-.08-1.2-.12-1.8-.12-1.78 0-3 1.08-3 3.08v2.35H9V13h2.2v7"/></svg>
}
function Instagram({ size = 24, ...props }: PlatformIconProps) {
  return <svg aria-hidden="true" viewBox="0 0 24 24" width={size} height={size} fill="none" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round" {...props}><rect x="4" y="4" width="16" height="16" rx="5"/><circle cx="12" cy="12" r="3.6"/><circle cx="17.2" cy="6.9" r=".7" fill="currentColor" stroke="none"/></svg>
}

