const automateViews=["overview","lab","broadcast-rules","cadence","recovery","channel-health","engagement","distribution","reconciliation","runs","exceptions"] as const
const automateLabels:Record<string,string>={overview:"OVERVIEW",lab:"AUTOMATION LAB","broadcast-rules":"120 BROADCAST RULES",cadence:"CADENCE",recovery:"RECOVERY","channel-health":"CHANNEL HEALTH",engagement:"ENGAGEMENT",distribution:"DISTRIBUTION",reconciliation:"RECONCILIATION",runs:"RUNS",exceptions:"EXCEPTIONS"}
